const rawQuery = isPlainObject(input.query) ? input.query : {};
const rawHeaders = isPlainObject(input.headers) ? input.headers : {};
const headerMap = Object.fromEntries(Object.entries(rawHeaders).map(([key, value]) => [String(key).toLowerCase(), value]));

